import type { Meta, StoryObj } from "@storybook/vue3";
import { h, onBeforeUnmount, onMounted, ref } from "vue";
import { KozmosProgress, KozmosProgressTrack } from "../../index";

/**
 * Vue's Progress and ProgressTrack: the stories React's has, with the same
 * names and args, each inside the KozmosThemeProvider the Storybook's
 * decorator gives every story. test/parity draws each of React's in both
 * and holds Vue's render to React's. Generated by `port Progress`; the
 * stories React draws by hand written by hand. React's Box, Stack and Text
 * are not ported yet: these draw the element and classes each draws
 * (test/parity/progress.parity.spec.ts draws React's parts against them).
 */
type Args = Record<string, unknown>;
const SLOTS = ["label", "children"];

/** React's Text, as it draws: a paragraph of its size, weight and colour. */
const text = (size: string, weight = "normal", color = "default") =>
  `kozmos-reset kozmos-text kozmos-text-${size} kozmos-text-${weight} kozmos-text-start kozmos-text-${color}`;
/** React's Stack in a row, gap 4, centred and wrapping, as it draws. */
const ROW = "flex flex-row items-center justify-start flex-wrap gap-4";
const TONES = [
  "themed",
  "neutral",
  "success",
  "informative",
  "alert",
  "danger",
] as const;

const meta: Meta<Args> = {
  title: "Vue/Core/Feedback/Progress",
  component: KozmosProgress,
  // React's node props are Vue's slots: `children` the default slot, the
  // rest slots of their own names, each drawing its arg's text; React's
  // `className` is Vue's `class`.
  render: (args) => ({
    setup: () => () => {
      const props: Args = {};
      const slots: Record<string, () => string> = {};
      for (const [key, value] of Object.entries(args)) {
        if (!SLOTS.includes(key))
          props[key === "className" ? "class" : key] = value;
        else if (value !== undefined && value !== null)
          slots[key === "children" ? "default" : key] = () => String(value);
      }
      return h(KozmosProgress, props, slots);
    },
  }),
};

export default meta;
type Story = StoryObj<Args>;

export const Default: Story = {
  args: {
    "aria-label": "Download progress",
    value: 66,
    className: "w-3/5",
  },
};

// GAP-159: no value, so a quarter-wide segment sweeps from the inline start
// to the inline end every 2 s, and stands still in the middle under reduced
// motion. It is named "Loading" and says so once as it appears.
export const Indeterminate: Story = {
  args: {
    className: "w-3/5",
  },
};

// Decision 131 (GAP-038): a count out of a total, as a ring.
export const Circular: Story = {
  args: {
    shape: "circular",
    value: 66,
    label: "66%",
    "aria-label": "Upload progress",
  },
};

// GAP-159: the page's loading bar, 4 tall, edge to edge and square, fixed to
