// Progress moving after it appears. Left out of the visual review: what it
// draws depends on when the screenshot lands.
export const AnimatedUpdate: Story = {
  tags: ["no-visual"],
  render: () => ({
    components: { KozmosProgress },
    setup() {
      const progress = ref(13);
      let timer: ReturnType<typeof setTimeout> | undefined;
      onMounted(() => {
        timer = setTimeout(() => (progress.value = 66), 500);
      });
      onBeforeUnmount(() => clearTimeout(timer));
      return { progress };
    },
    template: `<KozmosProgress aria-label="Download progress" :value="progress" class="w-3/5" />`,
  }),
};
